ALTER POLICY merchant_tax_owner ON public.merchant_tax_profiles USING (user_id = (SELECT auth.uid()) AND coalesce((SELECT auth.jwt())->>'is_anonymous','false') = 'false') WITH CHECK (user_id = (SELECT auth.uid()) AND coalesce((SELECT auth.jwt())->>'is_anonymous','false') = 'false');
ALTER POLICY formalization_owner ON public.formalization_progress USING (user_id = (SELECT auth.uid()) AND coalesce((SELECT auth.jwt())->>'is_anonymous','false') = 'false') WITH CHECK (user_id = (SELECT auth.uid()) AND coalesce((SELECT auth.jwt())->>'is_anonymous','false') = 'false');
ALTER POLICY formalization_docs_read ON storage.objects USING (bucket_id='formalizacion-documentos' AND (storage.foldername(name))[1]=(SELECT auth.uid())::text AND coalesce((SELECT auth.jwt())->>'is_anonymous','false') = 'false');
ALTER POLICY formalization_docs_create ON storage.objects WITH CHECK (bucket_id='formalizacion-documentos' AND (storage.foldername(name))[1]=(SELECT auth.uid())::text AND lower(storage.extension(name)) IN ('pdf','jpg','jpeg','png') AND coalesce((SELECT auth.jwt())->>'is_anonymous','false') = 'false');
ALTER POLICY formalization_docs_delete ON storage.objects USING (bucket_id='formalizacion-documentos' AND (storage.foldername(name))[1]=(SELECT auth.uid())::text AND coalesce((SELECT auth.jwt())->>'is_anonymous','false') = 'false');